	public BuiltInArchiveNode(DataTypeStore store, DtFilterState filterState) : base(store, filterState)
    {
	}

	/* @Override */
	public Icon getIcon(bool expanded) {
		Icon baseIcon = expanded ? OPEN_ICON : CLOSED_ICON;
		MultiIcon multiIcon = new MultiIcon(baseIcon);
		return multiIcon;
	}

